import {
  isSessionProcessing,
  markSessionIdle,
  markSessionProcessing,
  syncProcessingSessions,
} from './useSessionProtection';

test('processing actions preserve the stale idle-ack guard', () => {
  const sessionId = 'processing-actions-session';

  markSessionProcessing(sessionId, { statusText: 'Working', canInterrupt: true });
  assert.equal(isSessionProcessing(sessionId), true);

  markSessionIdle(sessionId, { ifStartedBefore: 0 });
  assert.equal(isSessionProcessing(sessionId), true);

  markSessionIdle(sessionId);
  assert.equal(isSessionProcessing(sessionId), false);
});

test('server synchronization replaces expired processing entries', () => {
  const sessionId = 'processing-sync-session';

  syncProcessingSessions([{ sessionId, startedAt: 1 }]);
  assert.equal(isSessionProcessing(sessionId), true);

  syncProcessingSessions([]);
  assert.equal(isSessionProcessing(sessionId), false);
});

import { useSyncExternalStore } from 'react';

export interface SessionActivity {
  /** Provider-supplied status line; null renders the default activity label. */
  statusText: string | null;
  canInterrupt: boolean;
  /** When this request was first marked as processing (client clock). */
  startedAt: number;
}

export type SessionActivityMap = ReadonlyMap<string, SessionActivity>;

export type SessionActivitySnapshot = {
  sessionId: string;
  statusText?: string | null;
  canInterrupt?: boolean;
  startedAt?: number;
};

export type MarkSessionProcessing = (
  sessionId?: string | null,
  activity?: { statusText?: string | null; canInterrupt?: boolean },
) => void;

export type MarkSessionIdle = (
  sessionId?: string | null,
  opts?: { ifStartedBefore?: number },
) => void;

export type SyncProcessingSessions = (
  sessions: readonly SessionActivitySnapshot[],
) => void;

const LOCAL_ACTIVITY_GRACE_MS = 10_000;

const sessionActivityMapsMatch = (
  left: SessionActivityMap,
  right: SessionActivityMap,
): boolean => {
  if (left.size !== right.size) {
    return false;
  }

  for (const [sessionId, leftActivity] of left) {
    const rightActivity = right.get(sessionId);
    if (
      !rightActivity
      || leftActivity.statusText !== rightActivity.statusText
      || leftActivity.canInterrupt !== rightActivity.canInterrupt
      || leftActivity.startedAt !== rightActivity.startedAt
    ) {
      return false;
    }
  }

  return true;
};

/**
 * External running-session store.
 *
 * Processing updates notify only components that explicitly call
 * `useProcessingSessions`. The module-level actions remain stable and can be
 * called by websocket handlers without subscribing the application shell.
 */
let processingSessionsSnapshot: SessionActivityMap = new Map();
const processingSessionListeners = new Set<() => void>();

function updateProcessingSessions(
  updater: (previous: SessionActivityMap) => SessionActivityMap,
): void {
  const next = updater(processingSessionsSnapshot);
  if (next === processingSessionsSnapshot) {
    return;
  }

  processingSessionsSnapshot = next;
  for (const listener of processingSessionListeners) {
    listener();
  }
}

function subscribeToProcessingSessions(listener: () => void): () => void {
  processingSessionListeners.add(listener);
  return () => {
    processingSessionListeners.delete(listener);
  };
}

function getProcessingSessionsSnapshot(): SessionActivityMap {
  return processingSessionsSnapshot;
}

/** Subscribes the calling component to the complete running-session map. */
export function useProcessingSessions(): SessionActivityMap {
  return useSyncExternalStore(
    subscribeToProcessingSessions,
    getProcessingSessionsSnapshot,
    getProcessingSessionsSnapshot,
  );
}

/** Reads whether a session is running without subscribing the caller. */
export function isSessionProcessing(sessionId: string): boolean {
  return processingSessionsSnapshot.has(sessionId);
}

export const markSessionProcessing: MarkSessionProcessing = (sessionId, activity) => {
  if (!sessionId) {
    return;
  }

  updateProcessingSessions((previous) => {
    const existing = previous.get(sessionId);
    const next: SessionActivity = {
      statusText:
        activity?.statusText !== undefined ? activity.statusText : existing?.statusText ?? null,
      canInterrupt: activity?.canInterrupt ?? existing?.canInterrupt ?? true,
      startedAt: existing?.startedAt ?? Date.now(),
    };

    if (
      existing
      && existing.statusText === next.statusText
      && existing.canInterrupt === next.canInterrupt
    ) {
      return previous;
    }

    const updated = new Map(previous);
    updated.set(sessionId, next);
    return updated;
  });
};

export const markSessionIdle: MarkSessionIdle = (sessionId, opts) => {
  if (!sessionId) {
    return;
  }

  updateProcessingSessions((previous) => {
    const existing = previous.get(sessionId);
    if (!existing) {
      return previous;
    }

    // Ignore an idle acknowledgement sent before a newer request started.
    if (opts?.ifStartedBefore !== undefined && existing.startedAt >= opts.ifStartedBefore) {
      return previous;
    }

    const updated = new Map(previous);
    updated.delete(sessionId);
    return updated;
  });
};

export const syncProcessingSessions: SyncProcessingSessions = (sessions) => {
  const now = Date.now();

  updateProcessingSessions((previous) => {
    const incoming = new Map<string, SessionActivitySnapshot>();
    for (const session of sessions) {
      if (session.sessionId) {
        incoming.set(session.sessionId, session);
      }
    }

    const updated = new Map<string, SessionActivity>();
    for (const [sessionId, snapshot] of incoming) {
      const existing = previous.get(sessionId);
      const snapshotStartedAt =
        typeof snapshot.startedAt === 'number' && Number.isFinite(snapshot.startedAt) && snapshot.startedAt > 0
          ? snapshot.startedAt
          : undefined;

      updated.set(sessionId, {
        statusText:
          snapshot.statusText !== undefined ? snapshot.statusText : existing?.statusText ?? null,
        canInterrupt: snapshot.canInterrupt ?? existing?.canInterrupt ?? true,
        startedAt: snapshotStartedAt ?? existing?.startedAt ?? now,
      });
    }

    for (const [sessionId, activity] of previous) {
      if (!incoming.has(sessionId) && now - activity.startedAt < LOCAL_ACTIVITY_GRACE_MS) {
        updated.set(sessionId, activity);
      }
    }

    return sessionActivityMapsMatch(previous, updated) ? previous : updated;
  });
};

